// Generated Comprehensive Session 2 data from مرور جلسه دوم.tex
export const session2Intro = "\n<p>سلام به همهٔ دانشجویان عزیز کارشناسی آمار! به دومین جلسه از حل تمرین درس شیرین و بنیادین <strong>«روش‌های آماری»</strong> خوش آمدید.</p>\n<p>در این جلسه، از برآورد نقطه‌ای فراتر می‌رویم و وارد دنیای جذاب و کاربردی <strong>«برآورد فاصله‌ای و فواصل اطمینان (Confidence Intervals)»</strong> می‌شویم. به جای تکیه بر یک برآوردگر منفرد، یاد می‌گیریم چگونه با استفاده از <strong>روش کمیت محوری (Pivotal Quantity Method)</strong>، بازه‌هایی بسازیم که با سطح اطمینان مشخص (مثلاً ۹۵٪ یا ۹۹٪) پارامتر مجهول جامعه را در بر بگیرند.</p>\n\n<div class=\"table-wrap\">\n<table>\n<thead>\n<tr>\n<th>بخش</th>\n<th>موضوع آموزشی</th>\n<th>کمیت محوری و آماره</th>\n<th>کاربرد کلیدی</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>۱. مقدمه</strong></td>\n<td>منطق فاصله اطمینان و کمیت محوری</td>\n<td><span class=\"math inline\">\\(Q(\\underline{X};\\, \\theta)\\)</span> با توزیع مستقل از پارامتر</td>\n<td>رویکرد ریاضی ساخت بازه‌ها</td>\n</tr>\n<tr>\n<td><strong>۲. میانگین جامعه</strong></td>\n<td>فاصله اطمینان برای <span class=\"math inline\">\\(\\mu\\)</span> (<span class=\"math inline\">\\(\\sigma^2\\)</span> معلوم و نامعلوم)</td>\n<td><span class=\"math inline\">\\(Z \\sim N(0,1)\\)</span> و <span class=\"math inline\">\\(T \\sim t_{(n-1)}\\)</span></td>\n<td>برآورد میانگین قد، نمرات، مصرف و...</td>\n</tr>\n<tr>\n<td><strong>۳. اختلاف دو میانگین</strong></td>\n<td>فاصله اطمینان برای <span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span></td>\n<td><span class=\"math inline\">\\(Z\\)</span>، <span class=\"math inline\">\\(t\\)</span> ادغام‌شده (<span class=\"math inline\">\\(S_p\\)</span>) و تقریب ولچ</td>\n<td>مقایسه دو جامعه، دارو، روش تدریس</td>\n</tr>\n<tr>\n<td><strong>۴. واریانس جامعه</strong></td>\n<td>فاصله اطمینان برای <span class=\"math inline\">\\(\\sigma^2\\)</span> (<span class=\"math inline\">\\(\\mu\\)</span> معلوم و نامعلوم)</td>\n<td><span class=\"math inline\">\\(\\chi^2_{(n)}\\)</span> و <span class=\"math inline\">\\(\\chi^2_{(n-1)}\\)</span></td>\n<td>برآورد پراکندگی و دقت فرآیندها</td>\n</tr>\n<tr>\n<td><strong>۵. نسبت دو واریانس</strong></td>\n<td>فاصله اطمینان برای <span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span></td>\n<td><span class=\"math inline\">\\(F_{(n_1-1,\\, n_2-1)}\\)</span> (توزیع فیشر)</td>\n<td>بررسی همگنی واریانس‌ها قبل از آزمون میانگین</td>\n</tr>\n<tr>\n<td><strong>۶. مشاهدات زوجی</strong></td>\n<td>فاصله اطمینان برای اختلاف میانگین زوجی <span class=\"math inline\">\\(\\mu_d\\)</span></td>\n<td><span class=\"math inline\">\\(T = \\dfrac{\\bar{D}-\\mu_d}{S_d/\\sqrt{n}} \\sim t_{(n-1)}\\)</span></td>\n<td>آزمون‌های پیش‌آزمون و پس‌آزمون وابسته</td>\n</tr>\n<tr>\n<td><strong>۷ و ۸. نسبت‌ها</strong></td>\n<td>نسبت جامعه <span class=\"math inline\">\\(p\\)</span> و اختلاف دو نسبت <span class=\"math inline\">\\(p_1 - p_2\\)</span></td>\n<td>تقریب نرمال والد <span class=\"math inline\">\\(Z \\approx N(0,1)\\)</span></td>\n<td>نظرسنجی‌ها، نرخ قبولی، کنترل کیفیت</td>\n</tr>\n<tr>\n<td><strong>۹. جمع‌بندی و جداول</strong></td>\n<td>جدول جامع فرمول‌ها و جداول مقادیر بحرانی</td>\n<td>جداول <span class=\"math inline\">\\(Z\\)</span>, <span class=\"math inline\">\\(t\\)</span>, <span class=\"math inline\">\\(\\chi^2\\)</span>, <span class=\"math inline\">\\(F\\)</span></td>\n<td>مرور سریع قبل از امتحانات</td>\n</tr>\n</tbody>\n</table>\n</div>\n";
export const session2Sections = [
  {
    "id": "s-ta2-1",
    "title": "۱. مقدمه و کمیت محوری",
    "html": "\n<p>سلام به همهٔ دانشجویان عزیز کارشناسی آمار! به دومین جلسه از کلاس‌های حل تمرین درس شیرین و بنیادین <strong>«روش‌های آماری»</strong> خوش آمدید.</p>\n<p>گاهی وقت‌ها به جای یک عددِ تنها برای برآورد پارامتر، دنبال این هستیم که یک بازه به‌دست بیاوریم که با احتمال خیلی بالا، پارامتر نامعلوم جامعه را در بر بگیرد. به این مفهوم، <strong>برآورد فاصله‌ای و فواصل اطمینان (Confidence Intervals)</strong> می‌گویند.</p>\n\n<p>فرض کنید <span class=\"math inline\">\\(X_1, X_2, \\dots, X_n\\)</span> یک نمونه تصادفی از چگالی <span class=\"math inline\">\\(f_\\theta\\)</span> باشد که در آن <span class=\"math inline\">\\(\\theta \\in \\Theta\\)</span> پارامتر نامعلوم است. فرض کنید <span class=\"math inline\">\\(L(\\underline{X}) = L(X_1, \\dots, X_n)\\)</span> و <span class=\"math inline\">\\(U(\\underline{X}) = U(X_1, \\dots, X_n)\\)</span> دو آماره باشند که برای هر <span class=\"math inline\">\\(\\underline{X}\\)</span> داریم <span class=\"math inline\">\\(L(\\underline{X}) < U(\\underline{X}\\)</span>.</p>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | تعریف فاصله اطمینان</p>\n<p>هرگاه <strong>برای هر <span class=\"math inline\">\\(\\theta \\in \\Theta\\)</span></strong> داشته باشیم:</p>\n<span class=\"math display\">\\[P_\\theta\\big(L(\\underline{X}) < \\theta < U(\\underline{X})\\big) = 1 - \\alpha\\]</span>\n<p>آنگاه بازه تصادفی <span class=\"math inline\">\\(\\big(L(\\underline{X}),\\, U(\\underline{X})\\big)\\)</span> را یک <strong>فاصله اطمینان در سطح <span class=\"math inline\">\\(1-\\alpha\\)</span></strong> برای <span class=\"math inline\">\\(\\theta\\)</span> نامند و <span class=\"math inline\">\\(1-\\alpha\\)</span> <strong>ضریب اطمینان (Confidence Coefficient)</strong> نامیده می‌شود.</p>\n</blockquote>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">یادآوری کلاسی (تفسیر صحیح فاصله اطمینان ـ خیلی مهم و امتحانی!)</p>\n<p>در رابطه بالا، حواستان باشد که کران‌های <span class=\"math inline\">\\(L(\\underline{X})\\)</span> و <span class=\"math inline\">\\(U(\\underline{X})\\)</span> متغیرهای تصادفی هستند و پارامتر <span class=\"math inline\">\\(\\theta\\)</span> یک عدد ثابت ولی نامعلوم است.</p>\n<p>بعد از اینکه داده‌های نمونه را جمع‌آوری کردیم و داخل فرمول گذاشتیم، بازهٔ عددی که به دست می‌آید دیگر تصادفی نیست! بنابراین به زبان دقیق و درست آماری، نباید بگوییم <em>«احتمال اینکه <span class=\"math inline\">\\(\\theta\\)</span> توی این بازهٔ عددی بیفته برابره با <span class=\"math inline\">\\(1-\\alpha\\)</span>»</em>، بلکه اگر آزمایش و نمونه‌گیری را بارها و بارها تکرار کنیم، حدود <span class=\"math inline\">\\((1-\\alpha)100\\%\\)</span> از این بازه‌های ساخته‌شده شامل مقدار واقعی پارامتر خواهند بود.</p>\n</blockquote>\n\n<h3 class=\"ta-group-title\">روش به‌دست آوردن کران‌ها بر حسب کمیت محوری</h3>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">تعریف | کمیت محوری (Pivotal Quantity)</p>\n<p>فرض کنید <span class=\"math inline\">\\(Q = Q(X_1, \\dots, X_n;\\, \\theta)\\)</span> تابعی از نمونه تصادفی و پارامتر باشد که توزیع آن به پارامتر <span class=\"math inline\">\\(\\theta\\)</span> (و هیچ پارامتر نامعلوم دیگری) بستگی نداشته باشد؛ آنگاه <span class=\"math inline\">\\(Q\\)</span> را یک <strong>کمیت محوری</strong> می‌نامند.</p>\n</blockquote>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">تعریف | چندک (Quantile)</p>\n<p><span class=\"math inline\">\\(q_p\\)</span> را چندک <span class=\"math inline\">\\(p\\)</span>\\,ام متغیر تصادفی پیوسته <span class=\"math inline\">\\(Q\\)</span> می‌نامند هرگاه:</p>\n<span class=\"math display\">\\[P(Q < q_p) = P(Q \\le q_p) = p\\]</span>\n</blockquote>\n\n<p>حالا اگر این دو تعریف را کنار هم بگذاریم، به این نتیجهٔ بسیار مهم و کلیدی می‌رسیم:</p>\n<span class=\"math display\">\\[P\\left(q_{\\frac{\\alpha}{2}} < Q(X_1, \\dots, X_n;\\, \\theta) < q_{1-\\frac{\\alpha}{2}}\\right) = 1 - \\alpha\\]</span>\n<p>که در آن <span class=\"math inline\">\\(q_{\\alpha/2}\\)</span> و <span class=\"math inline\">\\(q_{1-\\alpha/2}\\)</span> به‌ترتیب چندک‌های <span class=\"math inline\">\\(\\frac{\\alpha}{2}\\)</span> و <span class=\"math inline\">\\(1-\\frac{\\alpha}{2}\\)</span> توزیع معلوم <span class=\"math inline\">\\(Q\\)</span> هستند. اکنون کافی است نامعادلهٔ فوق را بر حسب پارامتر <span class=\"math inline\">\\(\\theta\\)</span> حل کنیم تا به فاصله اطمینان <span class=\"math inline\">\\((L(\\underline{X}),\\, U(\\underline{X}))\\)</span> برسیم.</p>\n\n<blockquote class=\"book-box important\">\n<p class=\"box-title\">الگوی کلی | چگونه کمیت محوری مناسب را برای هر پارامتر انتخاب کنیم؟</p>\n<ol>\n<li><strong>انتخاب برآوردگر پایه‌ای:</strong> ابتدا برآوردگر نقطه‌ای طبیعی پارامتر هدف را در نظر می‌گیریم (مثلاً برای <span class=\"math inline\">\\(\\mu\\)</span> از <span class=\"math inline\">\\(\\bar{X}\\)</span>، برای <span class=\"math inline\">\\(\\sigma^2\\)</span> از <span class=\"math inline\">\\(S^2\\)</span> و برای <span class=\"math inline\">\\(p\\)</span> از <span class=\"math inline\">\\(\\hat{p}\\)</span>).</li>\n<li><strong>استانداردسازی یا تغییر مقیاس:</strong> برآوردگر را به گونه‌ای استاندارد می‌کنیم که پارامتر مجهول در آن ظاهر شود ولی توزیع احتمال حاصل هیچ پارامتر مجهولی نداشته باشد.</li>\n<li><strong>تشکیل بازه و معکوس‌سازی جبری:</strong> نامساوی احتمالاتی چندک‌ها را نوشته و با حل نامعادله، پارامتر مجهول را در مرکز بازه منزوی می‌کنیم.</li>\n</ol>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-2",
    "title": "۲. میانگین جامعه و قضیه t",
    "html": "\n<p>فرض کنید <span class=\"math inline\">\\(X_1, X_2, \\dots, X_n\\)</span> یک نمونه تصادفی از جامعهٔ نرمال <span class=\"math inline\">\\(N(\\mu, \\sigma^2)\\)</span> باشد. هدف برآورد کردن میانگین جامعه (<span class=\"math inline\">\\(\\mu\\)</span>) است. دو حالت اساسی وجود دارد:</p>\n\n<h3 class=\"ta-group-title\">الف) حالت واریانس معلوم (<span class=\"math inline\">\\(\\sigma^2\\)</span> معلوم)</h3>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">قضیه | ترکیب خطی متغیرهای تصادفی نرمال</p>\n<p>هر ترکیب خطی غیربدیهی از متغیرهای تصادفی نرمال <strong>مستقل</strong> (یا دارای توزیع <strong>نرمال توأم</strong>) دارای توزیع نرمال است.</p>\n</blockquote>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">یادآوری علمی | ضرورت شرط استقلال</p>\n<p>شرط <strong>استقلال</strong> (یا نرمال توأم بودن) در قضیه بالا ضروری است؛ زیرا اگر دو متغیر تصادفی تک‌به‌تک نرمال ولی وابسته و فاقد توزیع نرمال توأم باشند، مجموع آن‌ها لزوماً نرمال نیست. در اینجا چون <span class=\"math inline\">\\(X_1, \\dots, X_n\\)</span> نمونه تصادفی هستند، مستقل‌اند و شرط برقرار است.</p>\n</blockquote>\n\n<blockquote class=\"book-box important\">\n<p class=\"box-title\">منطق انتخاب کمیت محوری و چرایی توزیع <span class=\"math inline\">\\(Z \\sim N(0,1)\\)</span> (حالت <span class=\"math inline\">\\(\\sigma^2\\)</span> معلوم)</p>\n<p><strong>گام ۱ (چرا از <span class=\"math inline\">\\(\\bar{X}\\)</span> شروع می‌کنیم؟):</strong> برآوردگر نقطه‌ای نااریب و کارا برای <span class=\"math inline\">\\(\\mu\\)</span> همان میانگین نمونه <span class=\"math inline\">\\(\\bar{X} = \\frac{1}{n}\\sum_{i=1}^n X_i\\)</span> است.</p>\n<p><strong>گام ۲ (چرا <span class=\"math inline\">\\(\\bar{X} \\sim N(\\mu, \\frac{\\sigma^2}{n})\\)</span> می‌شود؟):</strong> میانگین نمونه به‌صورت <span class=\"math inline\">\\(\\bar{X} = \\frac{1}{n}X_1 + \\dots + \\frac{1}{n}X_n\\)</span> یک ترکیب خطی از متغیرهای نرمال مستقل است؛ بنابراین خود <span class=\"math inline\">\\(\\bar{X}\\)</span> نیز نرمال است:</p>\n<span class=\"math display\">\\[\\E(\\bar{X}) = \\E\\!\\left(\\frac{1}{n}\\sum_{i=1}^{n} X_i\\right) = \\frac{1}{n}(n\\mu) = \\mu\\]</span>\n<span class=\"math display\">\\[\\Var(\\bar{X}) = \\Var\\!\\left(\\frac{1}{n}\\sum_{i=1}^{n} X_i\\right) = \\frac{1}{n^2}\\sum_{i=1}^{n}\\Var(X_i) = \\frac{1}{n^2}(n\\sigma^2) = \\frac{\\sigma^2}{n}\\]</span>\n<p>پس <span class=\"math inline\">\\(\\bar{X} \\sim N(\\mu, \\frac{\\sigma^2}{n})\\)</span> و انحراف معیار آن برابر <span class=\"math inline\">\\(\\mathrm{SE}(\\bar{X}) = \\frac{\\sigma}{\\sqrt{n}}\\)</span> است.</p>\n<p><strong>گام ۳ (چرا <span class=\"math inline\">\\(Z = \\frac{\\bar{X}-\\mu}{\\sigma/\\sqrt{n}}\\)</span> نرمال استاندارد و کمیت محوری است؟):</strong> با استانداردسازی متغیر نرمال، داریم <span class=\"math inline\">\\(\\E(Z) = 0\\)</span> و <span class=\"math inline\">\\(\\Var(Z) = 1\\)</span>؛ بنابراین <span class=\"math inline\">\\(Z \\sim N(0,1)\\)</span>. چون <span class=\"math inline\">\\(\\sigma\\)</span> معلوم است، تنها پارامتر مجهول در <span class=\"math inline\">\\(Z\\)</span> خود <span class=\"math inline\">\\(\\mu\\)</span> است و توزیع آن به هیچ پارامتری وابسته نیست.</p>\n</blockquote>\n\n<p>به‌طور خلاصه با حل نامعادله بر حسب <span class=\"math inline\">\\(\\mu\\)</span>:</p>\n<span class=\"math display\">\\[P\\left(z_{\\frac{\\alpha}{2}} < \\frac{\\bar{X}-\\mu}{\\sigma/\\sqrt{n}} < z_{1-\\frac{\\alpha}{2}}\\right) = 1 - \\alpha \\implies P\\left(\\bar{X} - z_{1-\\frac{\\alpha}{2}}\\frac{\\sigma}{\\sqrt{n}} < \\mu < \\bar{X} - z_{\\frac{\\alpha}{2}}\\frac{\\sigma}{\\sqrt{n}}\\right) = 1 - \\alpha\\]</span>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">نکته تقارن توزیع نرمال</p>\n<p>به دلیل تقارن زنگوله‌ای توزیع نرمال استاندارد حول مبدا: <span class=\"math inline\">\\(z_{\\frac{\\alpha}{2}} = -z_{1-\\frac{\\alpha}{2}}\\)</span></p>\n</blockquote>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\mu\\)</span> در حالت <span class=\"math inline\">\\(\\sigma^2\\)</span> معلوم</p>\n<span class=\"math display\">\\[\\bar{X} \\pm z_{1-\\frac{\\alpha}{2}}\\,\\frac{\\sigma}{\\sqrt{n}} = \\left(\\bar{X} - z_{1-\\frac{\\alpha}{2}}\\frac{\\sigma}{\\sqrt{n}},\\; \\bar{X} + z_{1-\\frac{\\alpha}{2}}\\frac{\\sigma}{\\sqrt{n}}\\right)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال ۱ | چندک توزیع نمایی</p>\n<p>فرض کنید <span class=\"math inline\">\\(X \\sim \\operatorname{Exp}(2)\\)</span> (توزیع نمایی با پارامتر نرخ <span class=\"math inline\">\\(\\lambda = 2\\)</span>). چندک <span class=\"math inline\">\\(0.95\\)</span>\\,ام <span class=\"math inline\">\\(X\\)</span> چیست؟</p>\n<p><strong>حل:</strong> طبق تعریف چندک: <span class=\"math inline\">\\(F(x_{0.95}) = P(X \\le x_{0.95}) = 0.95\\)</span>. تابع توزیع تجمعی نمایی برابر <span class=\"math inline\">\\(1 - e^{-\\lambda x}\\)</span> است:</p>\n<span class=\"math display\">\\[1 - e^{-2 x_{0.95}} = 0.95 \\implies e^{-2 x_{0.95}} = 0.05 \\implies -2 x_{0.95} = \\ln(0.05) \\implies x_{0.95} = -\\frac{\\ln(0.05)}{2} \\approx \\frac{2.996}{2} \\approx 1.5\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال ۲ | چندک توزیع نرمال استاندارد</p>\n<p>فرض کنید <span class=\"math inline\">\\(X \\sim N(0,1)\\)</span>. چندک <span class=\"math inline\">\\(0.95\\)</span>\\,ام <span class=\"math inline\">\\(X\\)</span> چه عددی است؟</p>\n<p><strong>حل:</strong> طبق تعریف: <span class=\"math inline\">\\(P(X \\le z_{0.95}) = \\Phi(z_{0.95}) = 0.95\\)</span>. با مراجعه به جدول توزیع نرمال استاندارد، مقدار متناظر با احتمال <span class=\"math inline\">\\(0.95\\)</span> عدد <strong><span class=\"math inline\">\\(1.645\\)</span></strong> است.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی ۳ | برآورد قد دانشجویان با <span class=\"math inline\">\\(n=16\\)</span></p>\n<p>فرض کنید <span class=\"math inline\">\\(X_1, X_2, \\dots, X_{16} \\sim N(\\mu, 64)\\)</span> باشد. با فرض <span class=\"math inline\">\\(\\bar{X} = 172\\)</span>، یک فاصله اطمینان ۹۵٪ برای <span class=\"math inline\">\\(\\mu\\)</span> بنویسید.</p>\n</blockquote>\n\n<blockquote class=\"book-box solution\">\n<p class=\"box-title\">حل تشریحی</p>\n<p>داریم <span class=\"math inline\">\\(n = 16\\)</span>، <span class=\"math inline\">\\(\\sigma^2 = 64 \\implies \\sigma = 8\\)</span>، <span class=\"math inline\">\\(\\bar{X} = 172\\)</span> و <span class=\"math inline\">\\(1-\\alpha = 0.95 \\implies \\alpha = 0.05 \\implies 1-\\alpha/2 = 0.975\\)</span>.</p>\n<p>از جدول نرمال استاندارد: <span class=\"math inline\">\\(z_{0.975} = 1.96\\)</span>. خطای استاندارد:</p>\n<span class=\"math display\">\\[\\frac{\\sigma}{\\sqrt{n}} = \\frac{8}{\\sqrt{16}} = \\frac{8}{4} = 2\\]</span>\n<p>بنابراین فاصله اطمینان برابر است با:</p>\n<span class=\"math display\">\\[\\mu \\in \\left(172 - 1.96(2),\\; 172 + 1.96(2)\\right) = (172 - 3.92,\\; 172 + 3.92) = (168.08,\\, 175.92)\\]</span>\n</blockquote>\n\n<h3 class=\"ta-group-title\">نکات مهم درباره فاصله اطمینان</h3>\n<p>طول فاصله اطمینان حاصل برابر است با:</p>\n<span class=\"math display\">\\[L = U(\\underline{X}) - L(\\underline{X}) = 2 z_{1-\\frac{\\alpha}{2}}\\,\\frac{\\sigma}{\\sqrt{n}}\\]</span>\n<ol>\n<li>طول فاصله اطمینان تابعی از متغیرهای تصادفی نمونه نیست و یک <strong>مقدار ثابت قطعی</strong> است (چون <span class=\"math inline\">\\(\\sigma\\)</span> معلوم است).</li>\n<li>با <strong>افزایش حجم نمونه (<span class=\"math inline\">\\(n\\)</span>)</strong>، طول بازه کاهش یافته و برآورد دقیق‌تر می‌شود (<span class=\"math inline\">\\(L \\propto 1/\\sqrt{n}\\)</span>).</li>\n<li>با <strong>افزایش ضریب اطمینان (<span class=\"math inline\">\\(1-\\alpha\\)</span>)</strong>، مقدار <span class=\"math inline\">\\(z_{1-\\alpha/2}\\)</span> و در نتیجه طول بازه افزایش می‌یابد.</li>\n<li>فاصله اطمینان حاصل متقارن حول میانگین نمونه <span class=\"math inline\">\\(\\bar{X}\\)</span> است.</li>\n</ol>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">یادآوری علمی | شرط کوتاه‌ترین طول بازه</p>\n<p>کوتاه‌ترین بودن فاصله اطمینان «دم‌های برابر» به‌دلیل <strong>تقارن و تک‌مُدی بودن چگالی نرمال</strong> است. اگر چگالی نامتقارن باشد، تقسیم مساوی <span class=\"math inline\">\\(\\alpha/2\\)</span> لزوماً کوتاه‌ترین بازه را تولید نمی‌کند.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | تعیین حداقل حجم نمونه در حالت <span class=\"math inline\">\\(\\sigma^2\\)</span> معلوم</p>\n<p>در جامعه‌ای نرمال با واریانس معلوم <span class=\"math inline\">\\(\\sigma^2 = 25\\)</span>، می‌خواهیم میانگین جامعه (<span class=\"math inline\">\\(\\mu\\)</span>) را با ضریب اطمینان <span class=\"math inline\">\\(99\\%\\)</span> برآورد کنیم، به‌طوری که خطای برآورد حداکثر <span class=\"math inline\">\\(e = 1\\)</span> واحد باشد. حداقل چه تعداد نمونه باید انتخاب شود؟</p>\n</blockquote>\n\n<blockquote class=\"book-box solution\">\n<p class=\"box-title\">حل تشریحی</p>\n<p>از جدول <span class=\"math inline\">\\(Z\\)</span> داریم <span class=\"math inline\">\\(z_{0.995} = 2.576\\)</span>. شرط خطای مجاز عبارت است از <span class=\"math inline\">\\(e \\ge z_{1-\\alpha/2}\\frac{\\sigma}{\\sqrt{n}}\\)</span>. با حل بر حسب <span class=\"math inline\">\\(n\\)</span>:</p>\n<span class=\"math display\">\\[n \\ge \\left(\\frac{z_{1-\\frac{\\alpha}{2}}\\,\\sigma}{e}\\right)^2 = \\left(\\frac{2.576 \\times 5}{1}\\right)^2 = (12.88)^2 \\approx 165.89\\]</span>\n<p>چون حجم نمونه باید عدد صحیح باشد، به بالا گرد می‌کنیم: <strong><span class=\"math inline\">\\(n = 166\\)</span></strong> نمونه نیاز است.</p>\n</blockquote>\n\n<h3 class=\"ta-group-title\">ب) حالت واریانس نامعلوم (<span class=\"math inline\">\\(\\sigma^2\\)</span> مجهول)</h3>\n<p>در بیشتر کاربردهای واقعی، نه تنها <span class=\"math inline\">\\(\\mu\\)</span> بلکه واریانس جامعه <span class=\"math inline\">\\(\\sigma^2\\)</span> نیز نامعلوم است. بنابراین نمی‌توانیم از کمیت <span class=\"math inline\">\\(Z\\)</span> استفاده کنیم. راه‌حل جایگزینی <span class=\"math inline\">\\(\\sigma\\)</span> با واریانس نمونه <span class=\"math inline\">\\(S = \\sqrt{\\frac{1}{n-1}\\sum (X_i - \\bar{X})^2}\\)</span> است.</p>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">قضیه | توزیع کای‌دو</p>\n<p>اگر <span class=\"math inline\">\\(Z_1, Z_2, \\dots, Z_n \\sim N(0,1)\\)</span> متغیرهای تصادفی نرمال استاندارد مستقل باشند، آنگاه مجموع مربعات آن‌ها دارای توزیع کای‌دو با <span class=\"math inline\">\\(n\\)</span> درجه آزادی است:</p>\n<span class=\"math display\">\\[\\sum_{i=1}^{n} Z_i^2 = Z_1^2 + Z_2^2 + \\dots + Z_n^2 \\sim \\chi^2_{(n)}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">تعریف | توزیع <span class=\"math inline\">\\(t\\)</span> استیودنت</p>\n<p>اگر <span class=\"math inline\">\\(Z \\sim N(0,1)\\)</span> و <span class=\"math inline\">\\(Y \\sim \\chi^2_{(\\nu)}\\)</span> دو متغیر تصادفی مستقل باشند، متغیر تصادفی <span class=\"math inline\">\\(T\\)</span> تعریف‌شده به‌صورت زیر دارای توزیع <span class=\"math inline\">\\(t\\)</span> استیودنت با <span class=\"math inline\">\\(\\nu\\)</span> درجه آزادی است:</p>\n<span class=\"math display\">\\[T = \\frac{Z}{\\sqrt{Y / \\nu}} \\sim t_{(\\nu)}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">قضیه | جمع متغیرهای مستقل کای‌دو</p>\n<p>اگر متغیرهای کای‌دو <span class=\"math inline\">\\(X_1 \\sim \\chi^2_{(n_1)}\\)</span> و <span class=\"math inline\">\\(X_2 \\sim \\chi^2_{(n_2)}\\)</span> از یکدیگر مستقل باشند، آنگاه <span class=\"math inline\">\\(X_1 + X_2 \\sim \\chi^2_{(n_1 + n_2)}\\)</span>.</p>\n</blockquote>\n\n<h3 class=\"ta-group-title\">اثبات دقیق و گام‌به‌گام قضیه | آمارهٔ استیودنت <span class=\"math inline\">\\(T = \\frac{\\bar{X}-\\mu}{S/\\sqrt{n}} \\sim t_{(n-1)}\\)</span></h3>\n<p>طبق ویژگی‌های نمونه‌گیری از جامعه نرمال داریم:</p>\n<span class=\"math display\">\\[X_i \\sim N(\\mu, \\sigma^2) \\implies \\frac{X_i-\\mu}{\\sigma} \\sim N(0,1) \\implies \\left(\\frac{X_i-\\mu}{\\sigma}\\right)^2 \\sim \\chi^2_{(1)}\\]</span>\n<span class=\"math display\">\\[\\implies \\underbrace{\\sum_{i=1}^{n}\\frac{(X_i-\\mu)^2}{\\sigma^2} \\sim \\chi^2_{(n)}}_{\\text{رابطهٔ کمکی ۱}}\\]</span>\n<p>و برای میانگین نمونه:</p>\n<span class=\"math display\">\\[\\bar{X} \\sim N\\!\\left(\\mu, \\frac{\\sigma^2}{n}\\right) \\implies \\underbrace{\\frac{\\bar{X}-\\mu}{\\sigma/\\sqrt{n}} \\sim N(0,1)}_{(\\star)} \\implies \\underbrace{\\frac{n(\\bar{X}-\\mu)^2}{\\sigma^2} \\sim \\chi^2_{(1)}}_{\\text{رابطهٔ کمکی ۲}}\\]</span>\n<p>از طرفی با بسط دوجمله‌ای و با توجه به اینکه <span class=\"math inline\">\\(\\sum_{i=1}^n (X_i - \\bar{X}) = 0\\)</span> است، ضرب متقاطع حذف شده و داریم:</p>\n<span class=\"math display\">\\[\\sum_{i=1}^{n}(X_i-\\mu)^2 = \\sum_{i=1}^{n}(X_i-\\bar{X})^2 + n(\\bar{X}-\\mu)^2\\]</span>\n<p>با تقسیم طرفین بر <span class=\"math inline\">\\(\\sigma^2\\)</span>:</p>\n<span class=\"math display\">\\[\\underbrace{\\frac{\\sum_{i=1}^{n}(X_i-\\mu)^2}{\\sigma^2}}_{\\sim \\chi^2_{(n)}} = \\frac{\\sum_{i=1}^{n}(X_i-\\bar{X})^2}{\\sigma^2} + \\underbrace{\\frac{n(\\bar{X}-\\mu)^2}{\\sigma^2}}_{\\sim \\chi^2_{(1)}} \\implies \\underbrace{\\frac{\\sum_{i=1}^{n}(X_i-\\bar{X})^2}{\\sigma^2} = \\frac{(n-1)S^2}{\\sigma^2} \\sim \\chi^2_{(n-1)}}_{(\\star\\star)}\\]</span>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">یادآوری علمی (قضیه فیشر و استقلال <span class=\"math inline\">\\(\\bar{X}\\)</span> و <span class=\"math inline\">\\(S^2\\)</span>)</p>\n<p>در جامعه نرمال، میانگین نمونه <span class=\"math inline\">\\(\\bar{X}\\)</span> و واریانس نمونه <span class=\"math inline\">\\(S^2\\)</span> <strong>از یکدیگر مستقل‌اند</strong>. این استقلال دو نقش کلیدی در اثبات بالا دارد: اولاً اجازه می‌دهد از تساوی توابع مولد گشتاور نتیجه بگیریم <span class=\"math inline\">\\(\\frac{(n-1)S^2}{\\sigma^2} \\sim \\chi^2_{(n-1)}\\)</span>; ثانیاً شرط استقلال صورت <span class=\"math inline\">\\(Z\\)</span> و مخرج <span class=\"math inline\">\\(Y\\)</span> را در تعریف توزیع <span class=\"math inline\">\\(t\\)</span> برقرار می‌کند.</p>\n</blockquote>\n\n<p><strong>تشکیل آماره و ساده‌سازی نسبت:</strong> حال با قرار دادن رابطهٔ <span class=\"math inline\">\\((\\star)\\)</span> در صورت و رابطهٔ <span class=\"math inline\">\\((\\star\\star)\\)</span> در مخرج:</p>\n<span class=\"math display\">\\[T = \\frac{\\dfrac{\\bar{X}-\\mu}{\\sigma/\\sqrt{n}}}{\\sqrt{\\dfrac{(n-1)S^2 / \\sigma^2}{n-1}}} = \\frac{\\dfrac{\\sqrt{n}(\\bar{X}-\\mu)}{\\sigma}}{\\dfrac{S}{\\sigma}} = \\frac{\\bar{X}-\\mu}{S/\\sqrt{n}} \\sim t_{(n-1)}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\mu\\)</span> در حالت <span class=\"math inline\">\\(\\sigma^2\\)</span> نامعلوم</p>\n<span class=\"math display\">\\[\\bar{X} \\pm t_{1-\\frac{\\alpha}{2},\\, n-1}\\,\\frac{S}{\\sqrt{n}} = \\left(\\bar{X} - t_{1-\\frac{\\alpha}{2},\\, n-1}\\frac{S}{\\sqrt{n}},\\; \\bar{X} + t_{1-\\frac{\\alpha}{2},\\, n-1}\\frac{S}{\\sqrt{n}}\\right)\\]</span>\n<p>که <span class=\"math inline\">\\(t_{1-\\alpha/2, n-1}\\)</span> چندک <span class=\"math inline\">\\((1-\\alpha/2)\\)</span>\\,ام توزیع <span class=\"math inline\">\\(t\\)</span> با <span class=\"math inline\">\\(n-1\\)</span> درجه آزادی است و از تقارن داریم <span class=\"math inline\">\\(t_{\\alpha/2} = -t_{1-\\alpha/2}\\)</span>.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی ۴ | سرعت اتومبیل‌ها در جاده</p>\n<p>سرعت ۵ اتومبیل در یک جاده اندازه‌گیری و مشاهده می‌شود که دارای سرعت متوسط <span class=\"math inline\">\\(80\\text{ km/h}\\)</span> با انحراف معیار نمونه <span class=\"math inline\">\\(4\\text{ km/h}\\)</span> است. با فرض نرمال بودن، فاصله اطمینان ۹۵٪ برای میانگین سرعت خودروها بسازید.</p>\n</blockquote>\n\n<blockquote class=\"book-box solution\">\n<p class=\"box-title\">حل تشریحی</p>\n<p>اطلاعات: <span class=\"math inline\">\\(n = 5\\)</span>، <span class=\"math inline\">\\(\\bar{X} = 80\\)</span>، <span class=\"math inline\">\\(S = 4\\)</span>، درجه آزادی <span class=\"math inline\">\\(df = 4\\)</span> و <span class=\"math inline\">\\(1-\\alpha/2 = 0.975\\)</span>.</p>\n<p>از جدول <span class=\"math inline\">\\(t\\)</span> با ۴ درجه آزادی: <span class=\"math inline\">\\(t_{0.975,\\, 4} = 2.776\\)</span>.</p>\n<span class=\"math display\">\\[\\mu \\in 80 \\pm 2.776 \\times \\frac{4}{\\sqrt{5}} = 80 \\pm 2.776(1.789) = 80 \\pm 4.97 = (75.03,\\, 84.97)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | میانگین با واریانس نامعلوم در سطح ۹۹٪</p>\n<p>در یک آزمایش زیستی، نمونه‌ای به حجم <span class=\"math inline\">\\(n = 9\\)</span> از وزن موش‌های آزمایشگاهی میانگین <span class=\"math inline\">\\(\\bar{X} = 24.5\\)</span> گرم و واریانس نمونه <span class=\"math inline\">\\(S^2 = 3.24\\)</span> (<span class=\"math inline\">\\(S = 1.8\\)</span>) به دست داده است. یک فاصله اطمینان ۹۹٪ برای میانگین وزن موش‌های این نژاد بسازید.</p>\n</blockquote>\n\n<blockquote class=\"book-box solution\">\n<p class=\"box-title\">حل تشریحی</p>\n<p>با <span class=\"math inline\">\\(\\nu = n - 1 = 8\\)</span> و <span class=\"math inline\">\\(1-\\alpha/2 = 0.995\\)</span> از جدول <span class=\"math inline\">\\(t\\)</span> داریم <span class=\"math inline\">\\(t_{8,\\, 0.995} = 3.355\\)</span>:</p>\n<span class=\"math display\">\\[\\mu \\in 24.5 \\pm 3.355 \\times \\frac{1.8}{\\sqrt{9}} = 24.5 \\pm 3.355(0.60) = 24.5 \\pm 2.013 = (22.487,\\, 26.513)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">قضیه حد مرکزی (CLT)</p>\n<p>فرض کنید <span class=\"math inline\">\\(X_1, X_2, \\dots, X_n\\)</span> یک نمونه تصادفی مستقل با میانگین <span class=\"math inline\">\\(\\mu\\)</span> و واریانس متناهی <span class=\"math inline\">\\(\\sigma^2\\)</span> باشد (از هر توزیعی، نه لزوماً نرمال!). وقتی <span class=\"math inline\">\\(n \\to \\infty\\)</span> (در عمل <span class=\"math inline\">\\(n \\ge 30\\)</span>):</p>\n<span class=\"math display\">\\[\\frac{\\bar{X} - \\mu}{\\sigma / \\sqrt{n}} \\xrightarrow{d} N(0,1)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">یادآوری علمی (کاربرد CLT و قضیه اسلاتسکی)</p>\n<p>اگر جامعه نرمال نباشد اما حجم نمونه به اندازه کافی بزرگ باشد (<span class=\"math inline\">\\(n \\ge 30\\)</span>)، با توجه به CLT و قضیه اسلاتسکی، حتی با جایگذاری <span class=\"math inline\">\\(S\\)</span> به جای <span class=\"math inline\">\\(\\sigma\\)</span>، آماره <span class=\"math inline\">\\(\\frac{\\bar{X}-\\mu}{S/\\sqrt{n}}\\)</span> مجانباً نرمال استاندارد <span class=\"math inline\">\\(N(0,1)\\)</span> خواهد بود و می‌توان از چندک‌های <span class=\"math inline\">\\(Z\\)</span> استفاده کرد.</p>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-3",
    "title": "۳. اختلاف دو میانگین",
    "html": "\n<p>در مقایسه دو جامعهٔ مستقل نرمال <span class=\"math inline\">\\(X_{11}, \\dots, X_{1n_1} \\sim N(\\mu_1, \\sigma_1^2)\\)</span> و <span class=\"math inline\">\\(X_{21}, \\dots, X_{2n_2} \\sim N(\\mu_2, \\sigma_2^2)\\)</span>، هدف برآورد اختلاف میانگین‌ها (<span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span>) است. سه حالت متداول وجود دارد:</p>\n\n<h3 class=\"ta-group-title\">الف) واریانس‌ها معلوم (<span class=\"math inline\">\\(\\sigma_1^2, \\sigma_2^2\\)</span> معلوم)</h3>\n<p>چون <span class=\"math inline\">\\(\\bar{X}_1 \\sim N(\\mu_1, \\sigma_1^2/n_1)\\)</span> و <span class=\"math inline\">\\(\\bar{X}_2 \\sim N(\\mu_2, \\sigma_2^2/n_2)\\)</span> مستقل‌اند:</p>\n<span class=\"math display\">\\[\\bar{X}_1 - \\bar{X}_2 \\sim N\\!\\left(\\mu_1 - \\mu_2,\\; \\frac{\\sigma_1^2}{n_1} + \\frac{\\sigma_2^2}{n_2}\\right)\\]</span>\n<p>کمیت محوری نرمال استاندارد است:</p>\n<span class=\"math display\">\\[Z = \\frac{(\\bar{X}_1 - \\bar{X}_2) - (\\mu_1 - \\mu_2)}{\\sqrt{\\dfrac{\\sigma_1^2}{n_1} + \\dfrac{\\sigma_2^2}{n_2}}} \\sim N(0,1)\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span> (واریانس‌ها معلوم)</p>\n<span class=\"math display\">\\[(\\bar{X}_1 - \\bar{X}_2) \\pm z_{1-\\frac{\\alpha}{2}}\\sqrt{\\frac{\\sigma_1^2}{n_1} + \\frac{\\sigma_2^2}{n_2}}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی | نمرات دو کلاس A و B</p>\n<p>از کلاس اول نمونه‌ای به حجم ۱۰ با میانگین ۱۲ و انحراف معیار جامعه ۴، و از کلاس دوم نمونه‌ای به حجم ۱۰ با میانگین ۱۵ و انحراف معیار جامعه ۳ انتخاب شده است. فاصله اطمینان ۹۵٪ برای اختلاف میانگین نمرات دو کلاس بسازید.</p>\n<p><strong>حل:</strong> <span class=\"math inline\">\\(n_1 = 10, \\bar{X}_1 = 12, \\sigma_1 = 4\\)</span> و <span class=\"math inline\">\\(n_2 = 10, \\bar{X}_2 = 15, \\sigma_2 = 3\\)</span> و <span class=\"math inline\">\\(z_{0.975} = 1.96\\)</span>:</p>\n<span class=\"math display\">\\[(\\mu_1 - \\mu_2) \\in (12 - 15) \\pm 1.96\\sqrt{\\frac{16}{10} + \\frac{9}{10}} = -3 \\pm 1.96\\sqrt{2.5} = -3 \\pm 3.10 = (-6.10,\\, 0.10)\\]</span>\n<p>چون عدد ۰ در بازه قرار دارد، در سطح ۹۵٪ تفاوت معناداری بین میانگین نمرات دو کلاس اثبات نمی‌شود.</p>\n</blockquote>\n\n<h3 class=\"ta-group-title\">ب) واریانس‌ها نامعلوم ولی برابر (<span class=\"math inline\">\\(\\sigma_1^2 = \\sigma_2^2 = \\sigma^2\\)</span>)</h3>\n<p>برای برآورد واریانس مشترک <span class=\"math inline\">\\(\\sigma^2\\)</span>، واریانس‌های دو نمونه را ادغام می‌کنیم (Pooled Variance):</p>\n<span class=\"math display\">\\[S_p^2 = \\frac{(n_1 - 1)S_1^2 + (n_2 - 1)S_2^2}{n_1 + n_2 - 2}\\]</span>\n<p>کمیت محوری استیودنت با <span class=\"math inline\">\\(n_1 + n_2 - 2\\)</span> درجه آزادی عبارت است از:</p>\n<span class=\"math display\">\\[T = \\frac{(\\bar{X}_1 - \\bar{X}_2) - (\\mu_1 - \\mu_2)}{S_p\\sqrt{\\dfrac{1}{n_1} + \\dfrac{1}{n_2}}} \\sim t_{(n_1 + n_2 - 2)}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span> (واریانس‌های نامعلوم و برابر)</p>\n<span class=\"math display\">\\[(\\bar{X}_1 - \\bar{X}_2) \\pm t_{1-\\frac{\\alpha}{2},\\, n_1+n_2-2}\\, S_p\\sqrt{\\frac{1}{n_1} + \\frac{1}{n_2}}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | مقایسه دو روش تدریس با واریانس‌های برابر</p>\n<p>دو گروه دانشجو با دو شیوهٔ تدریس آموزش دیده‌اند:</p>\n<ul>\n<li>شیوه اول: <span class=\"math inline\">\\(n_1 = 12, \\bar{X}_1 = 78, S_1^2 = 25\\)</span></li>\n<li>شیوه دوم: <span class=\"math inline\">\\(n_2 = 10, \\bar{X}_2 = 71, S_2^2 = 36\\)</span></li>\n</ul>\n<p>با فرض نرمال بودن و برابری واریانس‌ها، فاصله اطمینان ۹۵٪ برای <span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span> به دست آورید.</p>\n<p><strong>حل:</strong> واریانس ادغام‌شده برابر است با:</p>\n<span class=\"math display\">\\[S_p^2 = \\frac{11(25) + 9(36)}{20} = \\frac{275 + 324}{20} = 29.95 \\implies S_p \\approx 5.473\\]</span>\n<p>با <span class=\"math inline\">\\(df = 20\\)</span> از جدول <span class=\"math inline\">\\(t\\)</span> داریم <span class=\"math inline\">\\(t_{0.975,\\, 20} = 2.086\\)</span>:</p>\n<span class=\"math display\">\\[(\\mu_1 - \\mu_2) \\in (78 - 71) \\pm 2.086(5.473)\\sqrt{\\frac{1}{12} + \\frac{1}{10}} = 7 \\pm 4.89 = (2.11,\\, 11.89)\\]</span>\n<p>چون تمام بازه مثبت است و صفر در آن نیست، روش اول به‌طور معناداری موفق‌تر بوده است.</p>\n</blockquote>\n\n<h3 class=\"ta-group-title\">ج) واریانس‌ها نامعلوم و نابرابر (<span class=\"math inline\">\\(\\sigma_1^2 \\ne \\sigma_2^2\\)</span> - تقریب ولچ)</h3>\n<p>در این حالت آماره دقیقاً استیودنت نیست (مسئله بهرنز-فیشر). از <strong>تقریب ولچ-ساترث‌ویت</strong> با درجه آزادی تعدیل‌شده استفاده می‌کنیم:</p>\n<span class=\"math display\">\\[\\nu^* = \\frac{\\left(\\dfrac{S_1^2}{n_1} + \\dfrac{S_2^2}{n_2}\\right)^2}{\\dfrac{(S_1^2 / n_1)^2}{n_1 - 1} + \\dfrac{(S_2^2 / n_2)^2}{n_2 - 1}}\\]</span>\n<p>که همیشه به سمت پایین گرد می‌شود: <span class=\"math inline\">\\(\\nu = \\lfloor \\nu^* \\rfloor\\)</span>.</p>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان تقریب ولچ (واریانس‌های نامعلوم و نابرابر)</p>\n<span class=\"math display\">\\[(\\bar{X}_1 - \\bar{X}_2) \\pm t_{1-\\frac{\\alpha}{2},\\, \\nu}\\sqrt{\\frac{S_1^2}{n_1} + \\frac{S_2^2}{n_2}}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | تقریب ولچ</p>\n<p>برای دو گروه با <span class=\"math inline\">\\(n_1 = 10, \\bar{X}_1 = 52, S_1^2 = 36\\)</span> و <span class=\"math inline\">\\(n_2 = 15, \\bar{X}_2 = 45, S_2^2 = 9\\)</span> با فرض واریانس‌های نابرابر، درجه آزادی ولچ برابر است با:</p>\n<span class=\"math display\">\\[\\nu^* = \\frac{(3.6 + 0.6)^2}{\\frac{(3.6)^2}{9} + \\frac{(0.6)^2}{14}} = \\frac{17.64}{1.44 + 0.026} = \\frac{17.64}{1.466} \\approx 12.03 \\implies \\nu = 12\\]</span>\n<p>با <span class=\"math inline\">\\(t_{12,\\, 0.975} = 2.179\\)</span>:</p>\n<span class=\"math display\">\\[(\\mu_1 - \\mu_2) \\in (52 - 45) \\pm 2.179\\sqrt{3.6 + 0.6} = 7 \\pm 2.179(2.049) = 7 \\pm 4.46 = (2.54,\\, 11.46)\\]</span>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-4",
    "title": "۴. واریانس جامعه",
    "html": "\n<p>برای برآورد واریانس جامعهٔ نرمال (<span class=\"math inline\">\\(\\sigma^2\\)</span>)، از توزیع نامتقارن <strong>کای‌دو (<span class=\"math inline\">\\(\\chi^2\\)</span>)</strong> استفاده می‌شود. دو حالت بر اساس معلوم یا نامعلوم بودن میانگین جامعه وجود دارد:</p>\n\n<h3 class=\"ta-group-title\">الف) میانگین جامعه (<span class=\"math inline\">\\(\\mu\\)</span>) معلوم</h3>\n<p>کمیت محوری با <span class=\"math inline\">\\(n\\)</span> درجه آزادی عبارت است از:</p>\n<span class=\"math display\">\\[Q = \\sum_{i=1}^{n}\\frac{(X_i - \\mu)^2}{\\sigma^2} \\sim \\chi^2_{(n)}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\sigma^2\\)</span> (میانگین معلوم)</p>\n<p>به دلیل قرار گرفتن <span class=\"math inline\">\\(\\sigma^2\\)</span> در مخرج، جهت نامساوی معکوس شده و چندک بزرگتر در مخرج کران پایین می‌نشیند:</p>\n<span class=\"math display\">\\[\\left(\\frac{\\sum_{i=1}^{n}(X_i-\\mu)^2}{\\chi^2_{n,\\, 1-\\frac{\\alpha}{2}}},\\; \\frac{\\sum_{i=1}^{n}(X_i-\\mu)^2}{\\chi^2_{n,\\, \\frac{\\alpha}{2}}}\\right)\\]</span>\n</blockquote>\n\n<h3 class=\"ta-group-title\">ب) میانگین جامعه (<span class=\"math inline\">\\(\\mu\\)</span>) نامعلوم</h3>\n<p>با جایگزینی <span class=\"math inline\">\\(\\mu\\)</span> با <span class=\"math inline\">\\(\\bar{X}\\)</span>، یک درجه آزادی کسر می‌شود و کمیت محوری کای‌دو با <span class=\"math inline\">\\(n-1\\)</span> درجه آزادی حاصل می‌گردد:</p>\n<span class=\"math display\">\\[Q = \\frac{(n-1)S^2}{\\sigma^2} \\sim \\chi^2_{(n-1)}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\sigma^2\\)</span> (میانگین نامعلوم)</p>\n<span class=\"math display\">\\[\\left(\\frac{(n-1)S^2}{\\chi^2_{n-1,\\, 1-\\frac{\\alpha}{2}}},\\; \\frac{(n-1)S^2}{\\chi^2_{n-1,\\, \\frac{\\alpha}{2}}}\\right)\\]</span>\n<p>برای فاصله اطمینان انحراف معیار (<span class=\"math inline\">\\(\\sigma\\)</span>) کافی است از دو طرف جذر بگیرید.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی | واریانس نمونه <span class=\"math inline\">\\(S^2 = 4\\)</span> با <span class=\"math inline\">\\(n=10\\)</span></p>\n<p>نمونه‌ای تصادفی به حجم <span class=\"math inline\">\\(n = 10\\)</span> از جامعه نرمال با <span class=\"math inline\">\\(S^2 = 4\\)</span> به‌دست آمده است. فاصله اطمینان ۹۰٪ برای <span class=\"math inline\">\\(\\sigma^2\\)</span> بسازید.</p>\n<p><strong>حل:</strong> <span class=\"math inline\">\\(n = 10 \\implies df = 9\\)</span> و <span class=\"math inline\">\\(1-\\alpha = 0.90 \\implies \\alpha/2 = 0.05, 1-\\alpha/2 = 0.95\\)</span>.</p>\n<p>از جدول کای‌دو با ۹ درجه آزادی: <span class=\"math inline\">\\(\\chi^2_{9,\\, 0.05} = 3.325\\)</span> و <span class=\"math inline\">\\(\\chi^2_{9,\\, 0.95} = 16.919\\)</span>. صورت کسر <span class=\"math inline\">\\((n-1)S^2 = 9(4) = 36\\)</span> است:</p>\n<span class=\"math display\">\\[\\sigma^2 \\in \\left(\\frac{36}{16.919},\\; \\frac{36}{3.325}\\right) = (2.128,\\, 10.827)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | حالت <span class=\"math inline\">\\(\\mu\\)</span> معلوم</p>\n<p>فرض کنید <span class=\"math inline\">\\(n = 5\\)</span> مشاهده با میانگین معلوم <span class=\"math inline\">\\(\\mu = 10\\)</span> در دست است و مجموع مجذورات انحرافات برابر <span class=\"math inline\">\\(\\sum_{i=1}^5 (X_i - 10)^2 = 28.5\\)</span> می‌باشد. یک فاصله اطمینان ۹۵٪ برای <span class=\"math inline\">\\(\\sigma^2\\)</span> و <span class=\"math inline\">\\(\\sigma\\)</span> بسازید.</p>\n<p><strong>حل:</strong> با <span class=\"math inline\">\\(df = n = 5\\)</span> از جدول کای‌دو: <span class=\"math inline\">\\(\\chi^2_{5,\\, 0.025} = 0.831\\)</span> و <span class=\"math inline\">\\(\\chi^2_{5,\\, 0.975} = 12.833\\)</span>:</p>\n<span class=\"math display\">\\[\\sigma^2 \\in \\left(\\frac{28.5}{12.833},\\; \\frac{28.5}{0.831}\\right) = (2.221,\\, 34.296)\\]</span>\n<p>و برای انحراف معیار: <span class=\"math inline\">\\(\\sigma \\in (\\sqrt{2.221},\\, \\sqrt{34.296}) = (1.490,\\, 5.856)\\)</span>.</p>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-5",
    "title": "۵. نسبت دو واریانس",
    "html": "\n<p>در مقایسه دو خط تولید یا بررسی فرض برابری واریانس‌ها، نسبت واریانس‌های دو جامعهٔ نرمال مستقل (<span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span>) برآورد می‌شود. کمیت مبنا در اینجا <strong>توزیع فیشر-اسندکور (<span class=\"math inline\">\\(F\\)</span>)</strong> است.</p>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">نکته بسیار مهم تفسیری (بررسی برابری واریانس‌ها)</p>\n<p>اگر عدد <strong>۱</strong> در فاصله اطمینان به‌دست‌آمده برای <span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span> قرار داشته باشد، در سطح اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> <strong>شواهد کافی برای رد فرض برابری واریانس‌ها (<span class=\"math inline\">\\(\\sigma_1^2 = \\sigma_2^2\\)</span>) وجود ندارد</strong> (برابری واریانس‌ها پذیرفتنی است)؛ اما اگر ۱ خارج از بازه باشد، واریانس دو جامعه تفاوت معنادار دارند.</p>\n</blockquote>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">تعریف | توزیع فیشر <span class=\"math inline\">\\(F\\)</span></p>\n<p>اگر <span class=\"math inline\">\\(V \\sim \\chi^2_{(n_1)}\\)</span> و <span class=\"math inline\">\\(U \\sim \\chi^2_{(n_2)}\\)</span> دو متغیر کای‌دو مستقل باشند، نسبت زیر دارای توزیع <span class=\"math inline\">\\(F\\)</span> با درجات آزادی <span class=\"math inline\">\\(n_1\\)</span> و <span class=\"math inline\">\\(n_2\\)</span> است:</p>\n<span class=\"math display\">\\[\\frac{V / n_1}{U / n_2} \\sim F_{(n_1, n_2)}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box important\">\n<p class=\"box-title\">منطق انتخاب کمیت محوری برای نسبت دو واریانس (چرا توزیع <span class=\"math inline\">\\(F\\)</span>؟)</p>\n<p>برای ساخت کمیت محوری که فقط شامل نسبت <span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span> باشد (و نه تک‌تک پارامترها)، کمیت محوری کای‌دو جامعه دوم (تقسیم بر درجه آزادی‌اش) را بر کمیت محوری کای‌دو جامعه اول (تقسیم بر درجه آزادی‌اش) تقسیم می‌کنیم. حاصل دقیقاً تعریف توزیع فیشر است و نسبت واریانس‌ها در آن منزوی می‌شود.</p>\n</blockquote>\n\n<h3 class=\"ta-group-title\">الف) حالت میانگین‌های دو جامعه (<span class=\"math inline\">\\(\\mu_1, \\mu_2\\)</span>) معلوم</h3>\n<p>از جلسات قبل می‌دانیم:</p>\n<span class=\"math display\">\\[\\frac{\\sum_{i=1}^{n_1}(X_{1i}-\\mu_1)^2}{\\sigma_1^2} \\sim \\chi^2_{(n_1)}, \\qquad \\frac{\\sum_{i=1}^{n_2}(X_{2i}-\\mu_2)^2}{\\sigma_2^2} \\sim \\chi^2_{(n_2)}\\]</span>\n<p>با تشکیل نسبت کای‌دوها تقسیم بر درجات آزادی:</p>\n<span class=\"math display\">\\[\\frac{\\dfrac{\\sum_{i=1}^{n_2}(X_{2i}-\\mu_2)^2}{\\sigma_2^2 n_2}}{\\dfrac{\\sum_{i=1}^{n_1}(X_{1i}-\\mu_1)^2}{\\sigma_1^2 n_1}} \\sim F_{(n_2, n_1)} \\implies \\frac{\\sigma_1^2}{\\sigma_2^2}\\cdot\\frac{n_1\\sum_{i=1}^{n_2}(X_{2i}-\\mu_2)^2}{n_2\\sum_{i=1}^{n_1}(X_{1i}-\\mu_1)^2} \\sim F_{(n_2, n_1)}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span> در حالت <span class=\"math inline\">\\(\\mu_1, \\mu_2\\)</span> معلوم</p>\n<span class=\"math display\">\\[\\left(\\frac{\\sum_{i=1}^{n_1}(X_{1i}-\\mu_1)^2 / n_1}{\\sum_{i=1}^{n_2}(X_{2i}-\\mu_2)^2 / n_2}\\, F_{\\frac{\\alpha}{2},\\, n_2, n_1},\\; \\frac{\\sum_{i=1}^{n_1}(X_{1i}-\\mu_1)^2 / n_1}{\\sum_{i=1}^{n_2}(X_{2i}-\\mu_2)^2 / n_2}\\, F_{1-\\frac{\\alpha}{2},\\, n_2, n_1}\\right)\\]</span>\n</blockquote>\n\n<h3 class=\"ta-group-title\">ب) حالت میانگین‌های دو جامعه (<span class=\"math inline\">\\(\\mu_1, \\mu_2\\)</span>) نامعلوم</h3>\n<p>با جایگزینی میانگین‌ها با <span class=\"math inline\">\\(\\bar{X}_1\\)</span> و <span class=\"math inline\">\\(\\bar{X}_2\\)</span>، کمیت محوری فیشر به شکل زیر درمی‌آید:</p>\n<span class=\"math display\">\\[F = \\frac{(n_2-1)S_2^2 / [\\sigma_2^2(n_2-1)]}{(n_1-1)S_1^2 / [\\sigma_1^2(n_1-1)]} = \\frac{S_2^2}{S_1^2}\\cdot\\frac{\\sigma_1^2}{\\sigma_2^2} \\sim F_{(n_2-1,\\, n_1-1)}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای <span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span> در حالت <span class=\"math inline\">\\(\\mu_1, \\mu_2\\)</span> نامعلوم</p>\n<span class=\"math display\">\\[\\left(\\frac{S_1^2}{S_2^2}\\, F_{\\frac{\\alpha}{2},\\, n_2-1,\\, n_1-1},\\; \\frac{S_1^2}{S_2^2}\\, F_{1-\\frac{\\alpha}{2},\\, n_2-1,\\, n_1-1}\\right)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی | روش دو مرحله‌ای بررسی برابری دو جامعه</p>\n<p>از جامعهٔ اول نمونه‌ای به حجم <span class=\"math inline\">\\(n_1 = 10\\)</span> با <span class=\"math inline\">\\(\\bar{X}_1 = 10\\)</span> و <span class=\"math inline\">\\(S_1^2 = 8\\)</span> و از جامعهٔ دوم نمونه‌ای به حجم <span class=\"math inline\">\\(n_2 = 9\\)</span> با <span class=\"math inline\">\\(\\bar{X}_2 = 8\\)</span> و <span class=\"math inline\">\\(S_2^2 = 16\\)</span> در دست است. بر اساس یک فاصله اطمینان ۹۵٪، در مورد برابری میانگین دو جامعه اظهار نظر کنید.</p>\n</blockquote>\n\n<blockquote class=\"book-box solution\">\n<p class=\"box-title\">حل کامل دو مرحله‌ای</p>\n<p><strong>مرحله ۱ (بررسی برابری واریانس‌ها):</strong> با درجات آزادی <span class=\"math inline\">\\(n_2 - 1 = 8\\)</span> و <span class=\"math inline\">\\(n_1 - 1 = 9\\)</span> از جدول <span class=\"math inline\">\\(F\\)</span>:</p>\n<span class=\"math display\">\\[F_{0.975,\\, 8, 9} = 4.10, \\qquad F_{0.025,\\, 8, 9} = \\frac{1}{F_{0.975,\\, 9, 8}} = \\frac{1}{4.36} \\approx 0.229\\]</span>\n<span class=\"math display\">\\[\\frac{\\sigma_1^2}{\\sigma_2^2} \\in \\left(\\frac{8}{16}\\times 0.229,\\; \\frac{8}{16}\\times 4.10\\right) = (0.115,\\, 2.05)\\]</span>\n<p>چون عدد ۱ در این بازه قرار دارد، فرض برابری واریانس‌ها (<span class=\"math inline\">\\(\\sigma_1^2 = \\sigma_2^2\\)</span>) پذیرفتنی است.</p>\n<p><strong>مرحله ۲ (فاصله اطمینان برای <span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span> با واریانس مشترک):</strong></p>\n<span class=\"math display\">\\[S_p^2 = \\frac{9(8) + 8(16)}{10 + 9 - 2} = \\frac{200}{17} \\approx 11.76 \\implies S_p \\approx 3.43, \\qquad t_{17,\\, 0.975} = 2.110\\]</span>\n<span class=\"math display\">\\[(\\mu_1 - \\mu_2) \\in (10 - 8) \\pm 2.110(3.43)\\sqrt{\\frac{1}{10} + \\frac{1}{9}} = 2 \\pm 3.32 = (-1.32,\\, 5.32)\\]</span>\n<p>چون عدد ۰ در این بازه قرار دارد، در سطح ۹۵٪ شواهد کافی برای رد برابری میانگین دو جامعه وجود ندارد.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | مقایسه دقت دو دستگاه اندازه‌گیری</p>\n<p>واریانس خطای دستگاه اول روی <span class=\"math inline\">\\(n_1 = 13\\)</span> نمونه برابر <span class=\"math inline\">\\(S_1^2 = 9.6\\)</span> و برای دستگاه دوم روی <span class=\"math inline\">\\(n_2 = 16\\)</span> نمونه برابر <span class=\"math inline\">\\(S_2^2 = 4.0\\)</span> است. فاصله اطمینان ۹۰٪ برای <span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span> بسازید.</p>\n<p><strong>حل:</strong> درجات آزادی <span class=\"math inline\">\\(df_2 = 15\\)</span> و <span class=\"math inline\">\\(df_1 = 12\\)</span> است. از جدول <span class=\"math inline\">\\(F\\)</span> داریم <span class=\"math inline\">\\(F_{0.95,\\, 15, 12} = 2.62\\)</span> و <span class=\"math inline\">\\(F_{0.05,\\, 15, 12} = \\frac{1}{F_{0.95,\\, 12, 15}} = \\frac{1}{2.48} \\approx 0.403\\)</span>:</p>\n<span class=\"math display\">\\[\\frac{\\sigma_1^2}{\\sigma_2^2} \\in \\left(\\frac{9.6}{4.0}\\times 0.403,\\; \\frac{9.6}{4.0}\\times 2.62\\right) = (0.97,\\, 6.29)\\]</span>\n<p>چون <span class=\"math inline\">\\(1 \\in (0.97, 6.29)\\)</span> است، در سطح ۹۰٪ تفاوت معناداری در دقت دو دستگاه اثبات نمی‌شود.</p>\n</blockquote>\n\n<blockquote class=\"book-box important\">\n<p class=\"box-title\">نکته و اثبات ریاضی | رابطه چندک‌های معکوس توزیع <span class=\"math inline\">\\(F\\)</span></p>\n<p>اگر متغیر تصادفی <span class=\"math inline\">\\(H \\sim F_{(n_1, n_2)}\\)</span> باشد، آنگاه <span class=\"math inline\">\\(\\frac{1}{H} \\sim F_{(n_2, n_1)}\\)</span>. بنابراین:</p>\n<span class=\"math display\">\\[\\frac{1}{F_{p,\\, n_1, n_2}} = F_{1-p,\\, n_2, n_1}\\]</span>\n<p><strong>اثبات دقیق:</strong> طبق تعریف چندک:</p>\n<span class=\"math display\">\\[p = P\\left(H < F_{p,\\, n_1, n_2}\\right) = P\\left(\\frac{1}{H} > \\frac{1}{F_{p,\\, n_1, n_2}}\\right) = 1 - P\\left(\\frac{1}{H} < \\frac{1}{F_{p,\\, n_1, n_2}}\\right)\\]</span>\n<span class=\"math display\">\\[\\implies P\\left(\\frac{1}{H} < \\frac{1}{F_{p,\\, n_1, n_2}}\\right) = 1 - p \\implies \\frac{1}{F_{p,\\, n_1, n_2}} = F_{1-p,\\, n_2, n_1}\\]</span>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-6",
    "title": "۶. مشاهدات زوجی",
    "html": "\n<p>اگر مشاهدات دو جامعه از یکدیگر مستقل نباشند بلکه به‌صورت جفت‌های وابسته باشند (مانند نمرات قبل و بعد از آموزش یک فرد، یا مقایسه دو دارو روی دوقلوهای همسان)، باید از <strong>روش مشاهدات زوجی (Paired Data)</strong> استفاده شود.</p>\n\n<blockquote class=\"book-box definition\">\n<p class=\"box-title\">منطق تقلیل به مسئله تک‌نمونه</p>\n<p>برای هر جفت مشاهده <span class=\"math inline\">\\((X_{1i}, X_{2i})\\)</span>، متغیر تفاضل را تشکیل می‌دهیم:</p>\n<span class=\"math display\">\\[D_i = X_{1i} - X_{2i} \\quad (i = 1, 2, \\dots, n)\\]</span>\n<p>چون <span class=\"math inline\">\\(\\E(D_i) = \\mu_1 - \\mu_2 = \\mu_d\\)</span>، مسئله دقیقاً به ساخت فاصله اطمینان میانگین یک جامعه نرمال تبدیل می‌شود!</p>\n</blockquote>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> برای اختلاف میانگین زوجی (<span class=\"math inline\">\\(\\mu_d\\)</span>)</p>\n<p>میانگین و انحراف معیار تفاضل‌ها:</p>\n<span class=\"math display\">\\[\\bar{D} = \\frac{1}{n}\\sum_{i=1}^{n} D_i, \\qquad S_d^2 = \\frac{1}{n-1}\\sum_{i=1}^{n}(D_i - \\bar{D})^2\\]</span>\n<span class=\"math display\">\\[\\bar{D} \\pm t_{1-\\frac{\\alpha}{2},\\, n-1}\\,\\frac{S_d}{\\sqrt{n}}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی | نمرات درس روش‌های آماری و جبر خطی ۵ دانشجو</p>\n<p>نمرات ۵ دانشجو در دو درس روش‌های آماری (<span class=\"math inline\">\\(X_{1i}\\)</span>) و جبر خطی (<span class=\"math inline\">\\(X_{2i}\\)</span>) ثبت شده است:</p>\n<div class=\"table-wrap\">\n<table>\n<thead>\n<tr>\n<th>دانشجو</th>\n<th>درس ۱ (<span class=\"math inline\">\\(X_{1i}\\)</span>)</th>\n<th>درس ۲ (<span class=\"math inline\">\\(X_{2i}\\)</span>)</th>\n<th>تفاضل <span class=\"math inline\">\\(D_i = X_{1i} - X_{2i}\\)</span></th>\n</tr>\n</thead>\n<tbody>\n<tr><td>۱</td><td>۱۴</td><td>۱۶</td><td><span class=\"math inline\">\\(-2\\)</span></td></tr>\n<tr><td>۲</td><td>۱۷</td><td>۱۶</td><td><span class=\"math inline\">\\(+1\\)</span></td></tr>\n<tr><td>۳</td><td>۱۸</td><td>۱۶</td><td><span class=\"math inline\">\\(+2\\)</span></td></tr>\n<tr><td>۴</td><td>۱۱</td><td>۱۶</td><td><span class=\"math inline\">\\(-5\\)</span></td></tr>\n<tr><td>۵</td><td>۱۵</td><td>۱۷</td><td><span class=\"math inline\">\\(-2\\)</span></td></tr>\n</tbody>\n</table>\n</div>\n<p>فاصله اطمینان ۹۵٪ برای <span class=\"math inline\">\\(\\mu_d\\)</span> بسازید.</p>\n</blockquote>\n\n<blockquote class=\"book-box solution\">\n<p class=\"box-title\">حل تشریحی</p>\n<p>تفاضل‌ها: <span class=\"math inline\">\\(D_i = -2, 1, 2, -5, -2\\)</span>. میانگین تفاضل‌ها:</p>\n<span class=\"math display\">\\[\\bar{D} = \\frac{-2 + 1 + 2 - 5 - 2}{5} = -1.2\\]</span>\n<p>واریانس تفاضل‌ها:</p>\n<span class=\"math display\">\\[S_d^2 = \\frac{(-0.8)^2 + 2.2^2 + 3.2^2 + (-3.8)^2 + (-0.8)^2}{4} = \\frac{30.8}{4} = 7.7 \\implies S_d = 2.775\\]</span>\n<p>با <span class=\"math inline\">\\(t_{4,\\, 0.975} = 2.776\\)</span>:</p>\n<span class=\"math display\">\\[\\mu_d \\in -1.2 \\pm 2.776 \\times \\frac{2.775}{\\sqrt{5}} = -1.2 \\pm 3.44 = (-4.64,\\, 2.24)\\]</span>\n<p>چون عدد ۰ در این بازه قرار دارد، در سطح ۹۵٪ تفاوت معناداری بین میانگین نمرات دو درس وجود ندارد.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | پیش و پس از دوره آموزشی</p>\n<p>برای <span class=\"math inline\">\\(n = 10\\)</span> کارمند، میانگین اختلاف کارایی پس از دوره <span class=\"math inline\">\\(\\bar{D} = 4.2\\)</span> و انحراف معیار <span class=\"math inline\">\\(S_d = 1.5\\)</span> ثبت شده است. با <span class=\"math inline\">\\(\\nu = 9\\)</span> و <span class=\"math inline\">\\(t_{9,\\, 0.975} = 2.262\\)</span>:</p>\n<span class=\"math display\">\\[\\mu_d \\in 4.2 \\pm 2.262\\frac{1.5}{\\sqrt{10}} = 4.2 \\pm 1.07 = (3.13,\\, 5.27)\\]</span>\n<p>چون تمام بازه مثبت است، دوره آموزشی به طور معناداری کارایی را ارتقا داده است.</p>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-7",
    "title": "۷. نسبت و اختلاف دو نسبت",
    "html": "\n<p>در صفات کیفی دوحالته، پارامتر هدف نسبت موفقیت جامعه (<span class=\"math inline\">\\(p\\)</span>) است. با نمونه‌ای به حجم <span class=\"math inline\">\\(n\\)</span> و تعداد موفقیت <span class=\"math inline\">\\(X\\)</span>، برآوردگر نقطه‌ای <span class=\"math inline\">\\(\\hat{p} = X/n\\)</span> است.</p>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">یادآوری علمی | شرط اعتبار تقریب نرمال والد</p>\n<p>برای آنکه تقریب نرمال در فاصله اطمینان نسبت جامعه دقت مناسبی داشته باشد، باید شرایط تجربی زیر برقرار باشند:</p>\n<span class=\"math display\">\\[n\\hat{p} \\ge 5 \\qquad \\text{و} \\qquad n(1-\\hat{p}) \\ge 5\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> تقریبی برای نسبت جامعه (<span class=\"math inline\">\\(p\\)</span>)</p>\n<span class=\"math display\">\\[\\hat{p} \\pm z_{1-\\frac{\\alpha}{2}}\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} = \\left(\\hat{p} - z_{1-\\frac{\\alpha}{2}}\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}},\\; \\hat{p} + z_{1-\\frac{\\alpha}{2}}\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}\\right)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی | کالاهای معیوب یک شرکت</p>\n<p>در نمونه تصادفی به حجم ۱۰۰ از محصولات یک شرکت، ۵ تای آن‌ها معیوب است. یک فاصله اطمینان ۹۵٪ برای نسبت اقلام معیوب جامعه بسازید.</p>\n<p><strong>حل:</strong> <span class=\"math inline\">\\(n = 100, \\hat{p} = 0.05, 1-\\hat{p} = 0.95\\)</span> و <span class=\"math inline\">\\(z_{0.975} = 1.96\\)</span>:</p>\n<span class=\"math display\">\\[p \\in 0.05 \\pm 1.96\\sqrt{\\frac{0.05(0.95)}{100}} = 0.05 \\pm 1.96(0.0218) = 0.05 \\pm 0.043 = (0.007,\\, 0.093)\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | نظرسنجی با ضریب اطمینان ۹۹٪</p>\n<p>در یک نظرسنجی از ۴۰۰ شهروند، ۲۴۰ نفر رضایت داشته‌اند (<span class=\"math inline\">\\(\\hat{p} = 0.60\\)</span>). با <span class=\"math inline\">\\(z_{0.995} = 2.576\\)</span>:</p>\n<span class=\"math display\">\\[p \\in 0.60 \\pm 2.576\\sqrt{\\frac{0.60(0.40)}{400}} = 0.60 \\pm 2.576(0.0245) = 0.60 \\pm 0.063 = (0.537,\\, 0.663)\\]</span>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-8",
    "title": "۸. جدول جمع‌بندی فرمول‌ها",
    "html": "\n<p>در مقایسه دو جامعهٔ برنولی مستقل با نسبت‌های <span class=\"math inline\">\\(p_1\\)</span> و <span class=\"math inline\">\\(p_2\\)</span>، برآوردگر طبیعی <span class=\"math inline\">\\(\\hat{p}_1 - \\hat{p}_2\\)</span> است:</p>\n<span class=\"math display\">\\[\\E(\\hat{p}_1 - \\hat{p}_2) = p_1 - p_2, \\qquad \\Var(\\hat{p}_1 - \\hat{p}_2) = \\frac{p_1(1-p_1)}{n_1} + \\frac{p_2(1-p_2)}{n_2}\\]</span>\n\n<blockquote class=\"book-box result\">\n<p class=\"box-title\">فرمول کلیدی | فاصله اطمینان <span class=\"math inline\">\\(1-\\alpha\\)</span> تقریبی برای اختلاف دو نسبت (<span class=\"math inline\">\\(p_1 - p_2\\)</span>)</p>\n<span class=\"math display\">\\[(\\hat{p}_1 - \\hat{p}_2) \\pm z_{1-\\frac{\\alpha}{2}}\\sqrt{\\frac{\\hat{p}_1(1-\\hat{p}_1)}{n_1} + \\frac{\\hat{p}_2(1-\\hat{p}_2)}{n_2}}\\]</span>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال کلاسی | مقایسه دیدگاه دانشجویان پسر و دختر</p>\n<p>در یک نمونه تصادفی ۴۰۰ تایی شامل ۲۰۰ دانشجوی پسر و ۲۰۰ دانشجوی دختر، نظر آن‌ها درباره موضوعی پرسیده شد. ۱۶۰ پسر (<span class=\"math inline\">\\(\\hat{p}_1 = 160/200 = 0.80\\)</span>) و ۱۰۰ دختر (<span class=\"math inline\">\\(\\hat{p}_2 = 100/200 = 0.50\\)</span>) موافق بودند. فاصله اطمینان ۹۵٪ برای اختلاف نسبت موافقت دو جنس بسازید.</p>\n<p><strong>حل:</strong> با <span class=\"math inline\">\\(z_{0.975} = 1.96\\)</span>:</p>\n<span class=\"math display\">\\[(p_1 - p_2) \\in (0.80 - 0.50) \\pm 1.96\\sqrt{\\frac{0.80(0.20)}{200} + \\frac{0.50(0.50)}{200}} = 0.30 \\pm 1.96\\sqrt{0.0008 + 0.00125} = 0.30 \\pm 0.089 = (0.211,\\, 0.389)\\]</span>\n<p>چون تمام بازه مثبت است و صفر در آن نیست، موافقت پسران به‌طور معناداری بیشتر از دختران است.</p>\n</blockquote>\n\n<blockquote class=\"book-box example\">\n<p class=\"box-title\">مثال تکمیلی | کارآزمایی بالینی دارو در برابر دارونما</p>\n<p>از ۱۵۰ بیمار گروه داروی جدید، ۱۲۰ نفر بهبود یافتند (<span class=\"math inline\">\\(\\hat{p}_1 = 0.80\\)</span>) و از ۱۵۰ بیمار دارونما، ۹۶ نفر بهبود یافتند (<span class=\"math inline\">\\(\\hat{p}_2 = 0.64\\)</span>). با <span class=\"math inline\">\\(z_{0.975} = 1.96\\)</span>:</p>\n<span class=\"math display\">\\[(p_1 - p_2) \\in (0.80 - 0.64) \\pm 1.96\\sqrt{\\frac{0.80(0.20)}{150} + \\frac{0.64(0.36)}{150}} = 0.16 \\pm 0.100 = (0.060,\\, 0.260)\\]</span>\n<p>چون کل بازه مثبت است، داروی جدید در سطح ۹۵٪ نرخ بهبودی بالاتری نسبت به دارونما دارد.</p>\n</blockquote>\n"
  },
  {
    "id": "s-ta2-9",
    "title": "۹. پیوست جداول آماری",
    "html": "\n<p>برای مرور سریع قبل از امتحانات و حل تمارین، در جدول زیر تمام ۱۱ وضعیت استاندارد فواصل اطمینان به همراه کمیت محوری و فرمول دقیق بازه گردآوری شده است:</p>\n\n<div class=\"table-wrap\">\n<table>\n<thead>\n<tr>\n<th>پارامتر هدف</th>\n<th>شرایط و فروض جامعه</th>\n<th>توزیع کمیت محوری</th>\n<th>فاصله اطمینان <span class=\"math inline\">\\((1-\\alpha)\\)</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\mu\\)</span></strong></td>\n<td>جامعه نرمال (یا <span class=\"math inline\">\\(n\\)</span> بزرگ)، <span class=\"math inline\">\\(\\sigma^2\\)</span> معلوم</td>\n<td><span class=\"math inline\">\\(N(0,1)\\)</span></td>\n<td><span class=\"math inline\">\\(\\bar{X} \\pm z_{1-\\frac{\\alpha}{2}}\\,\\dfrac{\\sigma}{\\sqrt{n}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\mu\\)</span></strong></td>\n<td>جامعه نرمال، <span class=\"math inline\">\\(\\sigma^2\\)</span> نامعلوم</td>\n<td><span class=\"math inline\">\\(t_{(n-1)}\\)</span></td>\n<td><span class=\"math inline\">\\(\\bar{X} \\pm t_{1-\\frac{\\alpha}{2},\\, n-1}\\,\\dfrac{S}{\\sqrt{n}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span></strong></td>\n<td>دو جامعه مستقل، <span class=\"math inline\">\\(\\sigma_1^2, \\sigma_2^2\\)</span> معلوم</td>\n<td><span class=\"math inline\">\\(N(0,1)\\)</span></td>\n<td><span class=\"math inline\">\\((\\bar{X}_1 - \\bar{X}_2) \\pm z_{1-\\frac{\\alpha}{2}}\\sqrt{\\dfrac{\\sigma_1^2}{n_1}+\\dfrac{\\sigma_2^2}{n_2}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span></strong></td>\n<td>مستقل نرمال، <span class=\"math inline\">\\(\\sigma_1^2 = \\sigma_2^2\\)</span> نامعلوم و برابر</td>\n<td><span class=\"math inline\">\\(t_{(n_1+n_2-2)}\\)</span></td>\n<td><span class=\"math inline\">\\((\\bar{X}_1 - \\bar{X}_2) \\pm t_{1-\\frac{\\alpha}{2},\\, n_1+n_2-2}\\,S_p\\sqrt{\\dfrac{1}{n_1}+\\dfrac{1}{n_2}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\mu_1 - \\mu_2\\)</span></strong></td>\n<td>مستقل نرمال، <span class=\"math inline\">\\(\\sigma_1^2 \\ne \\sigma_2^2\\)</span> نامعلوم و نابرابر</td>\n<td><span class=\"math inline\">\\(t_{(\\nu^*)}\\)</span> (تقریب ولچ)</td>\n<td><span class=\"math inline\">\\((\\bar{X}_1 - \\bar{X}_2) \\pm t_{1-\\frac{\\alpha}{2},\\, \\nu}\\sqrt{\\dfrac{S_1^2}{n_1}+\\dfrac{S_2^2}{n_2}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\mu_d = \\mu_1 - \\mu_2\\)</span></strong></td>\n<td>مشاهدات زوجی (وابسته)</td>\n<td><span class=\"math inline\">\\(t_{(n-1)}\\)</span></td>\n<td><span class=\"math inline\">\\(\\bar{D} \\pm t_{1-\\frac{\\alpha}{2},\\, n-1}\\,\\dfrac{S_d}{\\sqrt{n}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\sigma^2\\)</span></strong></td>\n<td>جامعه نرمال، <span class=\"math inline\">\\(\\mu\\)</span> معلوم</td>\n<td><span class=\"math inline\">\\(\\chi^2_{(n)}\\)</span></td>\n<td><span class=\"math inline\">\\(\\left(\\dfrac{\\sum(X_i-\\mu)^2}{\\chi^2_{n,\\, 1-\\frac{\\alpha}{2}}},\\; \\dfrac{\\sum(X_i-\\mu)^2}{\\chi^2_{n,\\, \\frac{\\alpha}{2}}}\\right)\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\sigma^2\\)</span></strong></td>\n<td>جامعه نرمال، <span class=\"math inline\">\\(\\mu\\)</span> نامعلوم</td>\n<td><span class=\"math inline\">\\(\\chi^2_{(n-1)}\\)</span></td>\n<td><span class=\"math inline\">\\(\\left(\\dfrac{(n-1)S^2}{\\chi^2_{n-1,\\, 1-\\frac{\\alpha}{2}}},\\; \\dfrac{(n-1)S^2}{\\chi^2_{n-1,\\, \\frac{\\alpha}{2}}}\\right)\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(\\sigma_1^2 / \\sigma_2^2\\)</span></strong></td>\n<td>دو نمونه مستقل نرمال، میانگین‌ها نامعلوم</td>\n<td><span class=\"math inline\">\\(F_{(n_1-1,\\, n_2-1)}\\)</span></td>\n<td><span class=\"math inline\">\\(\\left(\\dfrac{S_1^2}{S_2^2}\\cdot\\dfrac{1}{F_{1-\\frac{\\alpha}{2},\\, n_1-1,\\, n_2-1}},\\; \\dfrac{S_1^2}{S_2^2}\\cdot F_{1-\\frac{\\alpha}{2},\\, n_2-1,\\, n_1-1}\\right)\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(p\\)</span></strong></td>\n<td>نمونه برنولی، <span class=\"math inline\">\\(n\\)</span> بزرگ</td>\n<td><span class=\"math inline\">\\(N(0,1)\\)</span> تقریبی</td>\n<td><span class=\"math inline\">\\(\\hat{p} \\pm z_{1-\\frac{\\alpha}{2}}\\sqrt{\\dfrac{\\hat{p}(1-\\hat{p})}{n}}\\)</span></td>\n</tr>\n<tr>\n<td><strong><span class=\"math inline\">\\(p_1 - p_2\\)</span></strong></td>\n<td>دو جامعه برنولی مستقل، <span class=\"math inline\">\\(n_1, n_2\\)</span> بزرگ</td>\n<td><span class=\"math inline\">\\(N(0,1)\\)</span> تقریبی</td>\n<td><span class=\"math inline\">\\((\\hat{p}_1 - \\hat{p}_2) \\pm z_{1-\\frac{\\alpha}{2}}\\sqrt{\\dfrac{\\hat{p}_1(1-\\hat{p}_1)}{n_1}+\\dfrac{\\hat{p}_2(1-\\hat{p}_2)}{n_2}}\\)</span></td>\n</tr>\n</tbody>\n</table>\n</div>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">فرمول‌های کمکی جدول</p>\n<p><strong>واریانس ادغام‌شده:</strong> <span class=\"math inline\">\\(S_p^2 = \\dfrac{(n_1 - 1)S_1^2 + (n_2 - 1)S_2^2}{n_1 + n_2 - 2}\\)</span></p>\n<p><strong>درجه آزادی ولچ:</strong> <span class=\"math inline\">\\(\\nu^* = \\dfrac{\\left(\\dfrac{S_1^2}{n_1} + \\dfrac{S_2^2}{n_2}\\right)^2}{\\dfrac{(S_1^2 / n_1)^2}{n_1 - 1} + \\dfrac{(S_2^2 / n_2)^2}{n_2 - 1}}\\)</span></p>\n</blockquote>\n\n<blockquote class=\"book-box reminder\">\n<p class=\"box-title\">پیوست جداول آماری کامل</p>\n<p>جداول کامل توزیع‌های نرمال مثبت و منفی، استیودنت، کای‌دو و فیشر همراه با رسم نمودارهای دقیق در نسخهٔ کامل PDF جزوه جلسه دوم (۴۰ صفحه) پیوست شده‌اند که از طریق دکمهٔ «دریافت جزوهٔ حل تمرین جلسه دوم PDF» در نوار کناری و بالای صفحه قابل دانلود است.</p>\n</blockquote>\n"
  }
];
